# sanity check: ESMC
from esm.models.esmc import ESMC
from esm.sdk.api import ESMProtein
import torch


def compute_logits(model: ESMC, sequence: str):
    protein = ESMProtein(sequence=sequence)
    assert protein.sequence is not None
    input_ids = model._tokenize([protein.sequence])
    logits = model(input_ids).sequence_logits.squeeze(0)[
        1:-1
    ]  # remove start and end tokens
    return logits


def sample_sequence(
    model: ESMC, logits: torch.Tensor, positions: list[int] = None
) -> str:
    """Sample a sequence based on the grammaticality scores at specified positions.
    Args:
        grammaticality (torch.Tensor): The grammaticality scores for each amino acid at each position.
        positions (list[int]): The positions in the sequence to sample from.
    Returns:
        str: The sampled sequence.
    """
    if positions is not None and len(positions) > 0:
        logits = logits[positions, :]
    # sampled_indices = torch.multinomial(grammaticality, num_samples=1)
    sampled_indices = torch.argmax(logits, dim=-1)
    sampled_sequence = model.tokenizer.convert_ids_to_tokens(
        sampled_indices.squeeze().tolist()
    )
    return sampled_sequence


if __name__ == "__main__":
    from mutate_score import load_esm_model, find_mutation_information, mutate_sequence

    model, alphabet = load_esm_model()
    sequence = ""
    sequence_masked = "MYVLLTILISVLVCEAVIRVS______"
    information = find_mutation_information(sequence, sequence_masked)
    original_aa = []
    positions = []
    mutated_aa = []
    for info in information:
        original_aa.append(info["original_aa"])
        positions.append(info["position"])
        mutated_aa.append(info["mutated_aa"])

    logits = compute_logits(model, sequence_masked)
    sampled_sequence = sample_sequence(model, logits, positions)
    reconstructed_sequence = mutate_sequence(
        sequence_masked, positions, sampled_sequence, False
    )
    assert len(reconstructed_sequence) == len(sequence_masked) == len(sequence)
    print("O:", sequence[:50])
    print("M:", sequence_masked[:50])
    print("R:", reconstructed_sequence[:50])

    # reconstruction
    logits = compute_logits(model, sequence)
    sequence_recon = sample_sequence(model, logits)
    information = find_mutation_information(sequence, sequence_recon)
    print(f"Reconstruction accuracy: {1 - (len(information) / len(sequence)):.2f}")
